      g.globalAlpha = .07; g.fillStyle = i % 2 ? '#fa3678' : '#50d9ec'; g.beginPath(); g.moveTo(x + 6, 20); g.lineTo(x - 15, 174); g.lineTo(x + 62, 174); g.closePath(); g.fill(); g.globalAlpha = 1;
    }
    // Crowd rows
    for (let row = 0; row < 5; row++) {
      for (let x = -4 + (row % 2) * 5; x < W; x += 13) {
        const y = 52 + row * 17, bob = Math.sin(state.anim / 13 + x * .2 + row) > .65 ? 1 : 0;
        const colors = ['#d64464', '#7161b9', '#efaa49', '#4b9eaa', '#d4c2e8'];
        rect(g, x, y + bob, 5, 5, '#d6a77f'); rect(g, x - 1, y + 5 + bob, 7, 6, colors[(x / 13 + row * 3 | 0) % colors.length]);
      }
    }
    rect(g, 0, 138, W, 13, '#1c1028'); rect(g, 0, 147, W, 4, '#51346d');
    // Ring apron
    g.beginPath(); g.moveTo(81, 156); g.lineTo(559, 156); g.lineTo(618, 333); g.lineTo(22, 333); g.closePath(); g.fillStyle = '#191024'; g.fill();
    g.strokeStyle = '#604080'; g.lineWidth = 2; g.stroke();
    g.beginPath(); g.moveTo(108, 167); g.lineTo(532, 167); g.lineTo(582, 315); g.lineTo(58, 315); g.closePath(); g.fillStyle = '#252047'; g.fill();
    // Canvas mat tiles and logo
    for (let x = 94; x < 565; x += 32) { g.strokeStyle = 'rgba(170,143,214,.12)'; g.beginPath(); g.moveTo(x, 168); g.lineTo(x - 16, 315); g.stroke(); }
    rect(g, 267, 213, 106, 28, '#39264f'); rect(g, 271, 217, 98, 20, '#261937');
    g.fillStyle = '#ffc857'; g.font = 'bold 13px monospace'; g.textAlign = 'center'; g.fillText('SLAM CIRCUIT', 320, 232);
    // Ropes and corner pads
    const ropes = ['#f0d7ff', '#ff5b83', '#f0d7ff'];
    ropes.forEach((color, i) => { const y = 177 + i * 44; g.strokeStyle = color; g.lineWidth = 3; g.beginPath(); g.moveTo(78 - i * 4, y); g.lineTo(562 + i * 4, y); g.stroke(); });
    [[78, 159], [554, 159], [24, 313], [606, 313]].forEach(([x, y]) => { rect(g, x - 5, y - 10, 14, 26, '#15101d'); rect(g, x - 4, y - 8, 12, 9, '#f1cb63'); rect(g, x - 4, y + 3, 12, 9, '#ea5270'); });
    // Wrestlers
    if (state.player && state.enemy) {
      drawArenaFighter(g, 220 + (state.shake ? Math.random() * state.shake - state.shake / 2 : 0), 242, state.player, false);
      drawArenaFighter(g, 414 + (state.shake ? Math.random() * state.shake - state.shake / 2 : 0), 242, state.enemy, true);
      if (state.anim % 95 < 3) { state.shake = Math.max(0, state.shake - 1); }
    } else {
      drawArenaFighter(g, 220, 244, fighters[0], false); drawArenaFighter(g, 414, 244, enemies[0], true);
    }
    // Ring lights, grain and scan glints
    for (let i = 0; i < 44; i++) { const x = (i * 97 + state.anim * (i % 3 + 1)) % W; const y = 52 + (i * 29) % 95; rect(g, x, y, 1, 1, i % 2 ? '#fff1c8' : '#8be9ef'); }
    if (state.flash > 0) { g.fillStyle = `rgba(255,60,65,${state.flash})`; g.fillRect(0, 0, W, H); state.flash = Math.max(0, state.flash - .025); }
    g.fillStyle = 'rgba(0,0,0,.14)'; for (let y = 0; y < H; y += 4) g.fillRect(0, y, W, 1);
  }
  function drawArenaFighter(g, x, floor, f, isEnemy) {
    const hpRatio = Math.max(0, f.hp / f.maxHp);
    // Drop shadow, legs
    rect(g, x - 31, floor - 4, 64, 7, 'rgba(0,0,0,.45)');
    rect(g, x - 17, floor - 35, 12, 32, '#191628'); rect(g, x + 5, floor - 35, 13, 32, '#191628');
    rect(g, x - 20, floor - 5, 18, 5, '#090711'); rect(g, x + 3, floor - 5, 20, 5, '#090711');
    // Torso silhouette
    rect(g, x - 23, floor - 79, 47, 42, f.color); rect(g, x - 29, floor - 76, 11, 28, f.color); rect(g, x + 18, floor - 77, 12, 29, f.color);
    rect(g, x - 25, floor - 48, 51, 7, f.trim);
    // Head and hair
    rect(g, x - 15, floor - 111, 30, 30, '#e4a77d'); rect(g, x - 18, floor - 105, 5, 12, '#e4a77d');
    rect(g, x - 17, floor - 114, 34, 9, '#211628'); rect(g, x - 19, floor - 110, 8, 8, '#211628'); rect(g, x + 11, floor - 110, 7, 7, '#211628');
    rect(g, x - 10, floor - 99, 5, 3, '#17111a'); rect(g, x + 5, floor - 99, 5, 3, '#17111a'); rect(g, x - 4, floor - 88, 10, 2, '#7d3944');
    // Wrist tape
    rect(g, x - 33, floor - 52, 12, 7, '#f0e2d4'); rect(g, x + 22, floor - 52, 12, 7, '#f0e2d4');
    // Stamina pip above sprite
    rect(g, x - 24, floor - 126, 48, 4, '#08050e'); rect(g, x - 23, floor - 125, 46 * hpRatio, 2, isEnemy ? '#ff5670' : '#ffc857');
    g.fillStyle = isEnemy ? '#ffbdd0' : '#fff1ae'; g.font = '8px monospace'; g.textAlign = 'center'; g.fillText(isEnemy ? f.tag : f.tag, x, floor - 131);
  }
  function floatText(text, xPercent, yPercent, kind) {
    const el = document.createElement('span'); el.className = `floater ${kind || ''}`; el.textContent = text;
    el.style.left = `${xPercent}%`; el.style.top = `${yPercent}%`; $('floaters').appendChild(el);
    setTimeout(() => el.remove(), 1050);
  }
  let audio;
  function beep(freq, duration, volume) {
    if (!state.sound) return;
    try {
      audio ||= new (window.AudioContext || window.webkitAudioContext)();
      if (audio.state === 'suspended') audio.resume();
      const oscillator = audio.createOscillator(), gain = audio.createGain();
      oscillator.type = 'square'; oscillator.frequency.value = freq; gain.gain.value = volume || .025;
      oscillator.connect(gain); gain.connect(audio.destination); oscillator.start(); gain.gain.exponentialRampToValueAtTime(.001, audio.currentTime + duration); oscillator.stop(audio.currentTime + duration);
    } catch (_) { /* Audio is an optional browser capability. */ }
  }
  function soundHit(freq) { beep(freq, .09, .035); setTimeout(() => beep(freq * .68, .08, .02), 45); }
  function soundTick() { if (Math.random() < .08) beep(450, .025, .009); }

  function openHelp() {
    state.paused = state.screen === 'battle';
    if (state.paused) state.playing = false;
    showScreen('help');
  }
  function closeHelp() {
    if (state.paused) { state.paused = false; showScreen('battle'); state.playing = true; render(); }
    else showScreen('title');
  }
  function restart() {
    state.playing = false; state.selected = null; state.player = null; state.enemy = null; state.heat = 0; state.rage = 0;
    showScreen('title');
  }

  $('btn-start').addEventListener('click', startSelect);
  $('btn-how').addEventListener('click', openHelp);
  $('btn-back-title').addEventListener('click', () => showScreen('title'));
  $('btn-enter-ring').addEventListener('click', beginRun);
  $('btn-endturn').addEventListener('click', endTurn);
  $('btn-skip-reward').addEventListener('click', skipReward);
  $('btn-restart').addEventListener('click', restart);
  $('btn-retry').addEventListener('click', restart);
  $('btn-help').addEventListener('click', openHelp);
  $('btn-pause').addEventListener('click', openHelp);
  $('btn-close-help').addEventListener('click', closeHelp);
  $('btn-help-back').addEventListener('click', closeHelp);
  $('btn-sound').addEventListener('click', () => {
    state.sound = !state.sound; $('btn-sound').classList.toggle('muted', !state.sound);
    $('btn-sound').textContent = state.sound ? '♪' : '×'; if (state.sound) beep(520, .06);
  });
  window.addEventListener('keydown', (event) => {
    if (event.repeat) return;
    if (event.key === 'Escape') {
      if (state.screen === 'help') closeHelp(); else if (state.screen === 'battle') openHelp(); return;
    }
    if (state.screen === 'title' && (event.key === 'Enter' || event.key === ' ')) { event.preventDefault(); startSelect(); return; }
    if (state.screen === 'select' && event.key === 'Enter' && state.selected) { beginRun(); return; }
    if (state.screen !== 'battle') return;
    if (event.key === ' ' || event.key === 'End') { event.preventDefault(); endTurn(); return; }
    const n = Number(event.key); if (n >= 1 && n <= 9) playCard(n - 1);
    if (event.key.toLowerCase() === 'h') openHelp();
  });

  function frame() { state.anim++; drawArena(); requestAnimationFrame(frame); }
  showScreen('title');
  requestAnimationFrame(frame);
})();

